253	## SQL Injection Prevention
254	
255	### DBI Placeholders
256	
257	```perl
258	use v5.36;
259	use DBI;
260	
261	my $dbh = DBI->connect($dsn, $user, $pass, {
262	    RaiseError => 1,
263	    PrintError => 0,
264	    AutoCommit => 1,
265	});
266	
267	# Good: Parameterized queries — always use placeholders
268	sub find_user($dbh, $email) {
269	    my $sth = $dbh->prepare('SELECT * FROM users WHERE email = ?');
270	    $sth->execute($email);
271	    return $sth->fetchrow_hashref;
272	}
273	
274	sub search_users($dbh, $name, $status) {
275	    my $sth = $dbh->prepare(
276	        'SELECT * FROM users WHERE name LIKE ? AND status = ? ORDER BY name'
277	    );
278	    $sth->execute("%$name%", $status);
279	    return $sth->fetchall_arrayref({});
280	}
281	
282	# Bad: String interpolation in SQL (SQLi vulnerability!)
283	sub bad_find($dbh, $email) {
284	    my $sth = $dbh->prepare("SELECT * FROM users WHERE email = '$email'");
285	    # If $email = "' OR 1=1 --", returns all users
286	    $sth->execute;
287	    return $sth->fetchrow_hashref;
288	}
289	```
290	
291	### Dynamic Column Allowlists
292	
293	```perl
294	use v5.36;
295	
296	# Good: Validate column names against an allowlist
297	sub order_by($dbh, $column, $direction) {
298	    my %allowed_cols = map { $_ => 1 } qw(name email created_at);
299	    my %allowed_dirs = map { $_ => 1 } qw(ASC DESC);
300	
301	    die "Invalid column: $column\n"    unless $allowed_cols{$column};
302	    die "Invalid direction: $direction\n" unless $allowed_dirs{uc $direction};
303	
304	    my $sth = $dbh->prepare("SELECT * FROM users ORDER BY $column $direction");
305	    $sth->execute;
306	    return $sth->fetchall_arrayref({});
307	}
308	
309	# Bad: Directly interpolating user-chosen column
310	sub bad_order($dbh, $column) {
311	    $dbh->prepare("SELECT * FROM users ORDER BY $column");  # SQLi!
312	}
313	```
314	
315	### DBIx::Class (ORM Safety)
316	
317	```perl
318	use v5.36;
319	
320	# DBIx::Class generates safe parameterized queries
321	my @users = $schema->resultset('User')->search({
322	    status => 'active',
323	    email  => { -like => '%@example.com' },
324	}, {
325	    order_by => { -asc => 'name' },
326	    rows     => 50,
327	});
328	```
